#!/usr/bin/env node
/**
 * Website on a phone, the search page (confirmed with the person via mockup); a tablet and a PC stay as they are. Replaces patch-web-search-phone (works whether
 * that one was run or not):
 *  - at the top: "Parts Fit with my Car" (when there is a garage car);
 *  - box 1: All brands; All models shows once a brand is chosen, All years once a model is chosen;
 *  - box 2: All sections; All parts shows once a section is chosen;
 *  - box 3: Any price, Any time, Best match on one line;
 *  - no "Your car" title and no "Brand:", "Model:", "Price:"... before the values (screen readers still hear them);
 *  - no second search box (the one at the top stays), no "Browse all parts" title, no "9 parts found" line; every gap 8 px.
 *
 *   node scripts/patch-web-search-phone-v2.js            dry run
 *   node scripts/patch-web-search-phone-v2.js --write    applies it (each changed file is saved as <file>.before-patch-web-search-phone-v2 first)
 * Then: website: Ctrl+F5
 */
const DATA = {"created": [], "anchored": [], "replaced": [{"file": "apps/web-storefront/components/SearchFilters.tsx", "what": "website search filters on a phone: three boxes with no titles and no labels (All brands, All models, All years · All sections, All parts · Any price, Any time, Best match), each next step shown once the one before is chosen", "done": "only the value", "from": ["\"use client\";\n\nimport { useEffect, useRef, useState } from \"react\";\nimport { useSearchParams } from \"next/navigation\";\nimport { fetchGeneration, fetchGenerationsForModel, fetchModelsForBrand, fetchPartsForCategory, fetchVehicleBrands, type CategoryPart, type VehicleBrand, type VehicleGeneration, type VehicleModel } from \"@/lib/api\";\nimport { pickName, type DictKey } from \"@/lib/i18n\";\nimport { DELIVERY_DAYS, filterHref, modelYears, noCar, pricePresets, readExtraFilters, toUsd } from \"@/lib/searchFilters\";\nimport { useCurrency } from \"./CurrencyProvider\";\nimport FitsMyCarToggle from \"./FitsMyCarToggle\";\nimport { useLang, useT } from \"./LangProvider\";\nimport { SaveSearchButton } from \"./SaveSearchButton\";\nimport { useLocRouter } from \"./useLocRouter\";\n\nexport interface FilterSection { id: string; nameEn: string; nameAr: string | null }\n\nconst pill = \"inline-flex min-h-10 items-center gap-1.5 whitespace-nowrap rounded-[10px] border-[1.5px] px-3 text-sm font-semibold\";\nconst chip = \"inline-flex min-h-8 items-center gap-2 rounded-full bg-navy px-3 text-xs font-bold text-white hover:bg-[#123f56]\";\nconst pop = \"absolute start-0 top-full z-30 mt-2 w-72 rounded-xl border border-[#c5d0d8] bg-white p-3 shadow-[0_12px_30px_rgba(10,49,68,0.18)]\";\nconst optionRow = (on: boolean) => `flex min-h-10 w-full items-center gap-2.5 rounded-lg px-2 text-start text-sm ${on ? \"bg-[#f4f8fb] font-bold text-navy\" : \"hover:bg-chalk\"}`;\n\nfunction Radio({ on }: { on: boolean }) {\n  return <span aria-hidden=\"true\" className={`size-4 flex-none rounded-full border-2 ${on ? \"border-[5px] border-navy\" : \"border-[#8696a2]\"}`} />;\n}\n\n/** One dropdown of the bar: a button showing \"Label: value\", and its panel. Only one is open at a time; a click outside or Escape closes it. */\nfunction Drop({ id, label, value, active, open, setOpen, disabled, alignEnd, children }: {\n  id: string; label: string; value: string; active: boolean; open: string | null; setOpen: (v: string | null) => void; disabled?: boolean; alignEnd?: boolean; children: React.ReactNode;\n}) {\n  const isOpen = open === id;\n  return (\n    <div className=\"relative\" data-drop={id}>\n      <button type=\"button\" aria-haspopup=\"true\" aria-expanded={isOpen} disabled={disabled} onClick={() => setOpen(isOpen ? null : id)}\n        className={`${pill} ${active ? \"border-navy bg-[#f4f8fb] text-ink\" : \"border-[#c5d0d8] bg-white text-ink\"} disabled:cursor-not-allowed disabled:opacity-50`}>\n        <span className=\"font-medium text-muted\">{label}:</span><span className=\"max-w-[12rem] truncate\">{value}</span>\n        <svg aria-hidden=\"true\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" className={`text-muted transition-transform ${isOpen ? \"rotate-180\" : \"\"}`}><path d=\"M6 9l6 6 6-6\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.4\" strokeLinecap=\"round\" strokeLinejoin=\"round\" /></svg>\n      </button>\n      {isOpen && <div role=\"dialog\" aria-label={label} className={`${pop} ${alignEnd ? \"start-auto end-0\" : \"\"}`}>{children}</div>}\n    </div>\n  );\n}\n\n/**\n * The filters of the results page, all in one place: the title with the \"Fits my car\" switch, then one box of dropdowns. Its first line is the car, chosen step by\n * step and filtering at EVERY step (a brand shows all its parts, then a model narrows to that model, then a year to that year); its second line is the section, the\n * part, the price, the delivery and the sort. Then the filters that are on, then the filters that are on as chips (each removed with its ×, or all with \"Clear all\") and \"Save this search\". The title and the number of parts come from the page.\n * Every choice is a new address (/search?...), so the server draws the filtered page and each filtered page has its own link.\n */\nexport function SearchFilters({ sections, heading }: { sections: FilterSection[]; heading?: React.ReactNode }) {\n  const params = useSearchParams();\n  const router = useLocRouter();\n  const lang = useLang();\n  const t = useT();\n  const { format, rate } = useCurrency();\n  const [open, setOpen] = useState<string | null>(null);\n  const root = useRef<HTMLDivElement>(null);\n\n  const q = params.get(\"q\") ?? \"\";\n  const category = params.get(\"category\") ?? \"\";\n  const part = params.get(\"part\") ?? \"\";\n  const extra = readExtraFilters((n) => params.get(n));\n  const section = sections.find((s) => s.id === category) ?? null;\n  const sectionName = section ? pickName(lang, section.nameEn, section.nameAr) : category;\n\n  // The parts of the chosen section, for the Part dropdown.\n  const [parts, setParts] = useState<{ category: string; list: CategoryPart[] } | null>(null);\n  useEffect(() => {\n    if (!category) return;\n    let current = true;\n    fetchPartsForCategory(category).then((list) => { if (current) setParts({ category, list }); }).catch(() => { if (current) setParts({ category, list: [] }); });\n    return () => { current = false; };\n  }, [category]);\n  const sectionParts = parts?.category === category ? parts.list : null;\n  const partInfo = sectionParts?.find((p) => p.nameEn === part);\n  const partName = partInfo ? pickName(lang, partInfo.nameEn, partInfo.nameAr) : part;\n\n  // A click outside the bar, or Escape, closes the open dropdown.\n  useEffect(() => {\n    if (!open) return;\n    const onDown = (e: MouseEvent) => { if (!(e.target as Element).closest?.(`[data-drop=\"${open}\"]`)) setOpen(null); };\n    const onKey = (e: KeyboardEvent) => { if (e.key === \"Escape\") setOpen(null); };\n    document.addEventListener(\"mousedown\", onDown);\n    document.addEventListener(\"keydown\", onKey);\n    return () => { document.removeEventListener(\"mousedown\", onDown); document.removeEventListener(\"keydown\", onKey); };\n  }, [open]);\n\n  // ---- The car, step by step. The address holds brandId, then modelId, then year (and the generation when only one was made that year). A car that arrives as a\n  // generation only (the garage car, an old link) is looked up once, so its brand and model show in the dropdowns.\n  const generationId = params.get(\"generationId\") ?? \"\";\n  const yearParam = Number(params.get(\"year\")) || null;\n  const modelParam = params.get(\"modelId\") ?? \"\";\n  const [genInfo, setGenInfo] = useState<(VehicleGeneration & { brandId: string }) | null>(null);\n  useEffect(() => {\n    if (!generationId || modelParam) return;\n    let current = true;\n    fetchGeneration(generationId).then((g) => { if (current) setGenInfo(g); }).catch(() => {});\n    return () => { current = false; };\n  }, [generationId, modelParam]);\n  const looked = genInfo?.id === generationId ? genInfo : null;\n  const carBrand = params.get(\"brandId\") || looked?.brandId || \"\";\n  const carModel = params.get(\"modelId\") || looked?.modelId || \"\";\n\n  const [brands, setBrands] = useState<VehicleBrand[] | null>(null);\n  useEffect(() => { let current = true; fetchVehicleBrands().then((b) => { if (current) setBrands(b); }).catch(() => { if (current) setBrands([]); }); return () => { current = false; }; }, []);\n  const [models, setModels] = useState<{ brand: string; list: VehicleModel[] } | null>(null);\n  useEffect(() => {\n    if (!carBrand) return;\n    let current = true;\n    fetchModelsForBrand(carBrand).then((list) => { if (current) setModels({ brand: carBrand, list }); }).catch(() => { if (current) setModels({ brand: carBrand, list: [] }); });\n    return () => { current = false; };\n  }, [carBrand]);\n  const [gens, setGens] = useState<{ model: string; list: VehicleGeneration[] } | null>(null);\n  useEffect(() => {\n    if (!carModel) return;\n    let current = true;\n    fetchGenerationsForModel(carModel).then((list) => { if (current) setGens({ model: carModel, list }); }).catch(() => { if (current) setGens({ model: carModel, list: [] }); });\n    return () => { current = false; };\n  }, [carModel]);\n  const brandModels = models?.brand === carBrand ? models.list : null;\n  const modelGens = gens?.model === carModel ? gens.list : null;\n  const years = modelGens ? modelYears(modelGens) : [];\n  const thisYear = new Date().getFullYear();\n  const gensOfYear = yearParam && modelGens ? modelGens.filter((g) => yearParam >= g.yearStart && yearParam <= (g.yearEnd ?? thisYear)) : [];\n  const brandInfo = brands?.find((b) => b.id === carBrand);\n  const modelInfo = brandModels?.find((m) => m.id === carModel);\n  const brandName = brandInfo ? pickName(lang, brandInfo.name, brandInfo.nameAr) : \"\";\n  const modelName = modelInfo ? pickName(lang, modelInfo.name, modelInfo.nameAr) : \"\";\n  const genName = modelGens?.find((g) => g.id === generationId)?.name ?? \"\";\n  const [brandQuery, setBrandQuery] = useState(\"\");\n  const shownBrands = (brands ?? []).filter((b) => !brandQuery.trim() || `${b.name} ${b.nameAr ?? \"\"}`.toLowerCase().includes(brandQuery.trim().toLowerCase()));\n  const chooseYear = (y: number) => {\n    const fitting = (modelGens ?? []).filter((g) => y >= g.yearStart && y <= (g.yearEnd ?? thisYear));\n    go({ ...noCar(), brandId: carBrand, modelId: carModel, year: y, generationId: fitting.length === 1 ? fitting[0].id : null });   // one generation that year: it is the car\n  };\n\n  const go = (change: Record<string, string | number | null>) => { setOpen(null); router.push(filterHref(params, change)); };\n\n  // Price: typed in the buyer's currency, kept in the address in dollars.\n  const shown = (usd: number | undefined) => (usd === undefined ? \"\" : String(Math.round(usd * rate)));\n  const [minText, setMinText] = useState(shown(extra.minPrice));\n  const [maxText, setMaxText] = useState(shown(extra.maxPrice));\n  useEffect(() => { if (open === \"price\") { setMinText(shown(extra.minPrice)); setMaxText(shown(extra.maxPrice)); } }, [open]);   // eslint-disable-line react-hooks/exhaustive-deps\n  const [p1, p2, p3] = pricePresets(rate);\n  const money = (amount: number) => format(toUsd(amount, rate));\n  const presets: Array<{ label: string; min: number | null; max: number | null }> = [\n    { label: t(\"sf_price_under\", { a: money(p1) }), min: null, max: p1 },\n    { label: t(\"sf_price_between\", { a: money(p1), b: money(p2) }), min: p1, max: p2 },\n    { label: t(\"sf_price_between\", { a: money(p2), b: money(p3) }), min: p2, max: p3 },\n    { label: t(\"sf_price_over\", { a: money(p3) }), min: p3, max: null },\n  ];\n  const priceText = extra.minPrice !== undefined && extra.maxPrice !== undefined ? t(\"sf_price_between\", { a: format(extra.minPrice), b: format(extra.maxPrice) })\n    : extra.maxPrice !== undefined ? t(\"sf_price_up_to\", { a: format(extra.maxPrice) })\n    : extra.minPrice !== undefined ? t(\"sf_price_from\", { a: format(extra.minPrice) }) : null;\n  const applyPrice = () => {\n    const min = Number(minText); const max = Number(maxText);\n    const minUsd = minText.trim() && min > 0 ? toUsd(min, rate) : null;\n    let maxUsd = maxText.trim() && max > 0 ? toUsd(max, rate) : null;\n    if (minUsd !== null && maxUsd !== null && maxUsd < minUsd) maxUsd = null;\n    go({ minPrice: minUsd, maxPrice: maxUsd });\n  };\n\n  const deliveryText = extra.maxDeliveryDays ? t(\"sf_delivery_within\", { n: extra.maxDeliveryDays }) : null;\n  const sorts: Array<[string, DictKey]> = [[\"\", \"sf_sort_best\"], [\"newest\", \"sf_sort_newest\"], [\"price_asc\", \"sf_sort_price_asc\"], [\"price_desc\", \"sf_sort_price_desc\"]];\n  const sortKey = (sorts.find(([v]) => v === (extra.sort ?? \"\")) ?? sorts[0])[1];\n\n  const chips: Array<{ key: string; label: string; change: Record<string, null> }> = [];\n  const carLabel = [brandName, modelName, yearParam ? String(yearParam) : \"\"].filter(Boolean).join(\" \");\n  if (carBrand && carLabel) chips.push({ key: \"car\", label: carLabel, change: noCar() });\n  if (q) chips.push({ key: \"q\", label: `“${q}”`, change: { q: null } });\n  if (category) chips.push({ key: \"category\", label: sectionName, change: { category: null, part: null } });\n  if (part) chips.push({ key: \"part\", label: partName, change: { part: null } });\n  if (priceText) chips.push({ key: \"price\", label: priceText, change: { minPrice: null, maxPrice: null } });\n  if (deliveryText) chips.push({ key: \"delivery\", label: deliveryText, change: { maxDeliveryDays: null } });\n  const clearAll = { ...noCar(), q: null, category: null, part: null, minPrice: null, maxPrice: null, maxDeliveryDays: null, sort: null };\n\n  return (\n    <div ref={root} className=\"mb-6\">\n      <div className=\"mb-4 flex flex-wrap items-end justify-between gap-4\">\n        <div className=\"min-w-0\">{heading}</div>\n        <div className=\"empty:hidden min-w-64\"><FitsMyCarToggle /></div>\n      </div>\n\n      <div className=\"rounded-xl border border-line bg-white\">\n      {/* Line 1: the car. Each step filters the results at once. */}\n      <div role=\"group\" aria-label={t(\"sf_your_car\")} className=\"flex flex-wrap items-center gap-2 border-b border-line p-2.5\">\n        <span className=\"px-1 text-sm font-bold text-navy\">{t(\"sf_your_car\")}</span>\n        <Drop id=\"brand\" label={t(\"sf_brand\")} value={brandName || (carBrand ? \"…\" : t(\"sf_all_brands\"))} active={!!carBrand} open={open} setOpen={(v) => { setOpen(v); setBrandQuery(\"\"); }}>\n          {(brands?.length ?? 0) > 8 && (\n            <input value={brandQuery} onChange={(e) => setBrandQuery(e.target.value)} placeholder={t(\"sf_search_brands\")} aria-label={t(\"sf_search_brands\")} autoFocus className=\"mb-2 w-full rounded-lg border-[1.5px] border-[#c5d0d8] px-2.5 py-2 text-sm\" />\n          )}\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!carBrand)} onClick={() => go(noCar())}><Radio on={!carBrand} />{t(\"sf_all_brands\")}</button>\n            {brands === null ? <p className=\"px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : shownBrands.map((b) => (\n              <button key={b.id} type=\"button\" className={optionRow(b.id === carBrand)} onClick={() => go({ ...noCar(), brandId: b.id })}><Radio on={b.id === carBrand} />{pickName(lang, b.name, b.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"model\" label={t(\"sf_model\")} value={modelName || (carModel ? \"…\" : carBrand ? t(\"sf_all_models\") : t(\"sf_pick_brand_first\"))} active={!!carModel} open={open} setOpen={setOpen} disabled={!carBrand}>\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!carModel)} onClick={() => go({ ...noCar(), brandId: carBrand })}><Radio on={!carModel} />{t(\"sf_all_models\")}</button>\n            {brandModels === null ? <p className=\"px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : brandModels.map((m) => (\n              <button key={m.id} type=\"button\" className={optionRow(m.id === carModel)} onClick={() => go({ ...noCar(), brandId: carBrand, modelId: m.id })}><Radio on={m.id === carModel} />{pickName(lang, m.name, m.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"year\" label={t(\"sf_year\")} value={yearParam ? String(yearParam) : carModel ? t(\"sf_all_years\") : t(\"sf_pick_model_first\")} active={!!yearParam} open={open} setOpen={setOpen} disabled={!carModel}>\n          <div className=\"grid max-h-80 grid-cols-3 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={`${optionRow(!yearParam)} col-span-3`} onClick={() => go({ ...noCar(), brandId: carBrand, modelId: carModel })}><Radio on={!yearParam} />{t(\"sf_all_years\")}</button>\n            {modelGens === null ? <p className=\"col-span-3 px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : years.map((y) => (\n              <button key={y} type=\"button\" className={`${optionRow(y === yearParam)} justify-center`} onClick={() => chooseYear(y)}>{y}</button>\n            ))}\n          </div>\n        </Drop>\n        {gensOfYear.length > 1 && (\n          <Drop id=\"generation\" label={t(\"sf_generation\")} value={genName || t(\"sf_any_generation\")} active={!!generationId} open={open} setOpen={setOpen}>\n            <div className=\"grid gap-0.5\">\n              <button type=\"button\" className={optionRow(!generationId)} onClick={() => go({ generationId: null, versionId: null })}><Radio on={!generationId} />{t(\"sf_any_generation\")}</button>\n              {gensOfYear.map((g) => <button key={g.id} type=\"button\" className={optionRow(g.id === generationId)} onClick={() => go({ generationId: g.id, versionId: null })}><Radio on={g.id === generationId} />{g.name}</button>)}\n            </div>\n          </Drop>\n        )}\n      </div>\n\n      {/* Line 2: what kind of part, and how it is listed. */}\n      <div role=\"group\" aria-label={t(\"sf_filters\")} className=\"flex flex-wrap items-center gap-2 p-2.5\">\n        <Drop id=\"section\" label={t(\"sf_section\")} value={category ? sectionName : t(\"all_sections\")} active={!!category} open={open} setOpen={setOpen}>\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!category)} onClick={() => go({ category: null, part: null })}><Radio on={!category} />{t(\"all_sections\")}</button>\n            {sections.map((s) => (\n              <button key={s.id} type=\"button\" className={optionRow(s.id === category)} onClick={() => go({ category: s.id, part: null })}><Radio on={s.id === category} />{pickName(lang, s.nameEn, s.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"part\" label={t(\"sf_part\")} value={part ? partName : category ? t(\"sf_all_parts\") : t(\"sf_pick_section_first\")} active={!!part} open={open} setOpen={setOpen} disabled={!category}>\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!part)} onClick={() => go({ part: null })}><Radio on={!part} />{t(\"sf_all_parts\")}</button>\n            {sectionParts === null ? <p className=\"px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : sectionParts.map((p) => (\n              <button key={p.id} type=\"button\" className={optionRow(p.nameEn === part)} onClick={() => go({ part: p.nameEn })}><Radio on={p.nameEn === part} />{pickName(lang, p.nameEn, p.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"price\" label={t(\"sf_price\")} value={priceText ?? t(\"sf_any_price\")} active={!!priceText} open={open} setOpen={setOpen}>\n          <form onSubmit={(e) => { e.preventDefault(); applyPrice(); }} className=\"grid gap-2\">\n            <div className=\"flex gap-2\">\n              <label className=\"min-w-0 flex-1\"><span className=\"sr-only\">{t(\"sf_min\")}</span><input inputMode=\"numeric\" value={minText} onChange={(e) => setMinText(e.target.value.replace(/[^\\d]/g, \"\"))} placeholder={t(\"sf_min\")} className=\"w-full rounded-lg border-[1.5px] border-[#c5d0d8] px-2.5 py-2 text-sm\" /></label>\n              <label className=\"min-w-0 flex-1\"><span className=\"sr-only\">{t(\"sf_max\")}</span><input inputMode=\"numeric\" value={maxText} onChange={(e) => setMaxText(e.target.value.replace(/[^\\d]/g, \"\"))} placeholder={t(\"sf_max\")} className=\"w-full rounded-lg border-[1.5px] border-[#c5d0d8] px-2.5 py-2 text-sm\" /></label>\n            </div>\n            <div className=\"grid gap-0.5\">\n              {presets.map((p) => {\n                const on = (p.min === null ? extra.minPrice === undefined : extra.minPrice === toUsd(p.min, rate)) && (p.max === null ? extra.maxPrice === undefined : extra.maxPrice === toUsd(p.max, rate));\n                return <button key={p.label} type=\"button\" className={optionRow(on)} onClick={() => go({ minPrice: p.min === null ? null : toUsd(p.min, rate), maxPrice: p.max === null ? null : toUsd(p.max, rate) })}><Radio on={on} />{p.label}</button>;\n              })}\n            </div>\n            <div className=\"flex gap-2\">\n              <button type=\"submit\" className=\"inline-flex min-h-10 flex-1 items-center justify-center rounded-[10px] bg-signal px-4 text-sm font-bold text-on-signal hover:bg-signal-dark\">{t(\"sf_show_results\")}</button>\n              {priceText && <button type=\"button\" onClick={() => go({ minPrice: null, maxPrice: null })} className=\"min-h-10 px-2 text-sm font-semibold text-navy underline underline-offset-4\">{t(\"clear\")}</button>}\n            </div>\n          </form>\n        </Drop>\n        <Drop id=\"delivery\" label={t(\"sf_delivery\")} value={deliveryText ?? t(\"sf_delivery_any\")} active={!!deliveryText} open={open} setOpen={setOpen}>\n          <div className=\"grid gap-0.5\">\n            <button type=\"button\" className={optionRow(!extra.maxDeliveryDays)} onClick={() => go({ maxDeliveryDays: null })}><Radio on={!extra.maxDeliveryDays} />{t(\"sf_delivery_any\")}</button>\n            {DELIVERY_DAYS.map((d) => <button key={d} type=\"button\" className={optionRow(extra.maxDeliveryDays === d)} onClick={() => go({ maxDeliveryDays: d })}><Radio on={extra.maxDeliveryDays === d} />{t(\"sf_delivery_within\", { n: d })}</button>)}\n          </div>\n        </Drop>\n        <div className=\"ms-auto\">\n          <Drop id=\"sort\" label={t(\"sf_sort\")} value={t(sortKey)} active={!!extra.sort} open={open} setOpen={setOpen} alignEnd>\n            <div className=\"grid gap-0.5\">\n              {sorts.map(([v, key]) => <button key={key} type=\"button\" className={optionRow((extra.sort ?? \"\") === v)} onClick={() => go({ sort: v || null })}><Radio on={(extra.sort ?? \"\") === v} />{t(key)}</button>)}\n            </div>\n          </Drop>\n        </div>\n      </div>\n      </div>\n\n      <div className=\"mt-3 flex flex-wrap items-center gap-2\">\n        {chips.map((c) => (\n          <button key={c.key} type=\"button\" onClick={() => go(c.change)} className={chip}>\n            <span className=\"max-w-[16rem] truncate\">{c.label}</span><span aria-hidden=\"true\" className=\"opacity-80\">×</span><span className=\"sr-only\">{t(\"clear\")}</span>\n          </button>\n        ))}\n        {chips.length > 1 && <button type=\"button\" onClick={() => go(clearAll)} className=\"min-h-8 px-1 text-sm font-bold text-navy underline underline-offset-4\">{t(\"sf_clear_all\")}</button>}\n        <span className=\"ms-auto\" />\n        <SaveSearchButton searchTerm={q || undefined} category={category || undefined} />\n      </div>\n    </div>\n  );\n}\n", "\"use client\";\n\nimport { useEffect, useRef, useState } from \"react\";\nimport { useSearchParams } from \"next/navigation\";\nimport { fetchGeneration, fetchGenerationsForModel, fetchModelsForBrand, fetchPartsForCategory, fetchVehicleBrands, type CategoryPart, type VehicleBrand, type VehicleGeneration, type VehicleModel } from \"@/lib/api\";\nimport { pickName, type DictKey } from \"@/lib/i18n\";\nimport { DELIVERY_DAYS, filterHref, modelYears, noCar, pricePresets, readExtraFilters, toUsd } from \"@/lib/searchFilters\";\nimport { useCurrency } from \"./CurrencyProvider\";\nimport FitsMyCarToggle from \"./FitsMyCarToggle\";\nimport { useLang, useT } from \"./LangProvider\";\nimport { SaveSearchButton } from \"./SaveSearchButton\";\nimport { useLocRouter } from \"./useLocRouter\";\n\nexport interface FilterSection { id: string; nameEn: string; nameAr: string | null }\n\nconst pill = \"inline-flex min-h-10 items-center gap-1.5 whitespace-nowrap rounded-[10px] border-[1.5px] px-3 text-sm font-semibold\";\nconst chip = \"inline-flex min-h-8 items-center gap-2 rounded-full bg-navy px-3 text-xs font-bold text-white hover:bg-[#123f56]\";\nconst pop = \"absolute start-0 top-full z-30 mt-2 w-72 rounded-xl border border-[#c5d0d8] bg-white p-3 shadow-[0_12px_30px_rgba(10,49,68,0.18)]\";\nconst optionRow = (on: boolean) => `flex min-h-10 w-full items-center gap-2.5 rounded-lg px-2 text-start text-sm ${on ? \"bg-[#f4f8fb] font-bold text-navy\" : \"hover:bg-chalk\"}`;\n\nfunction Radio({ on }: { on: boolean }) {\n  return <span aria-hidden=\"true\" className={`size-4 flex-none rounded-full border-2 ${on ? \"border-[5px] border-navy\" : \"border-[#8696a2]\"}`} />;\n}\n\n/** One dropdown of the bar: a button showing \"Label: value\", and its panel. Only one is open at a time; a click outside or Escape closes it. */\n// On a phone: phoneHidden hides a step until the one before it is chosen; stack puts the label small above the value, so three fit on one line.\n// Every panel opens under its box, as wide as the box (the box is the one positioned on a phone), so it never runs off the screen.\nfunction Drop({ id, label, value, active, open, setOpen, disabled, alignEnd, phoneHidden, stack, children }: {\n  id: string; label: string; value: string; active: boolean; open: string | null; setOpen: (v: string | null) => void; disabled?: boolean; alignEnd?: boolean; phoneHidden?: boolean; stack?: boolean; children: React.ReactNode;\n}) {\n  const isOpen = open === id;\n  return (\n    <div className={`relative max-sm:static ${stack ? \"min-w-0\" : \"\"} ${phoneHidden ? \"max-sm:hidden\" : \"\"}`} data-drop={id}>\n      <button type=\"button\" aria-haspopup=\"true\" aria-expanded={isOpen} disabled={disabled} onClick={() => setOpen(isOpen ? null : id)}\n        className={`${pill} ${stack ? \"max-sm:grid max-sm:w-full max-sm:grid-cols-[minmax(0,1fr)_auto] max-sm:gap-x-1 max-sm:gap-y-0 max-sm:px-2 max-sm:py-1 max-sm:text-start max-sm:leading-tight\" : \"\"} ${active ? \"border-navy bg-[#f4f8fb] text-ink\" : \"border-[#c5d0d8] bg-white text-ink\"} disabled:cursor-not-allowed disabled:opacity-50`}>\n        <span className={`font-medium text-muted ${stack ? \"max-sm:col-start-1 max-sm:text-[11px]\" : \"\"}`}>{label}<span className={stack ? \"max-sm:hidden\" : \"\"}>:</span></span><span className={`max-w-[12rem] truncate ${stack ? \"max-sm:col-start-1 max-sm:max-w-full\" : \"\"}`}>{value}</span>\n        <svg aria-hidden=\"true\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" className={`text-muted transition-transform ${stack ? \"max-sm:col-start-2 max-sm:row-span-2 max-sm:row-start-1 max-sm:self-center\" : \"\"} ${isOpen ? \"rotate-180\" : \"\"}`}><path d=\"M6 9l6 6 6-6\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.4\" strokeLinecap=\"round\" strokeLinejoin=\"round\" /></svg>\n      </button>\n      {isOpen && <div role=\"dialog\" aria-label={label} className={`${pop} ${alignEnd ? \"sm:start-auto sm:end-0\" : \"\"} max-sm:inset-x-0 max-sm:w-auto`}>{children}</div>}\n    </div>\n  );\n}\n\n/**\n * The filters of the results page, all in one place: the title with the \"Fits my car\" switch, then one box of dropdowns. Its first line is the car, chosen step by\n * step and filtering at EVERY step (a brand shows all its parts, then a model narrows to that model, then a year to that year); its second line is the section, the\n * part, the price, the delivery and the sort. Then the filters that are on, then the filters that are on as chips (each removed with its ×, or all with \"Clear all\") and \"Save this search\". The title and the number of parts come from the page.\n * Every choice is a new address (/search?...), so the server draws the filtered page and each filtered page has its own link.\n */\nexport function SearchFilters({ sections, heading }: { sections: FilterSection[]; heading?: React.ReactNode }) {\n  const params = useSearchParams();\n  const router = useLocRouter();\n  const lang = useLang();\n  const t = useT();\n  const { format, rate } = useCurrency();\n  const [open, setOpen] = useState<string | null>(null);\n  const root = useRef<HTMLDivElement>(null);\n\n  const q = params.get(\"q\") ?? \"\";\n  const category = params.get(\"category\") ?? \"\";\n  const part = params.get(\"part\") ?? \"\";\n  const extra = readExtraFilters((n) => params.get(n));\n  const section = sections.find((s) => s.id === category) ?? null;\n  const sectionName = section ? pickName(lang, section.nameEn, section.nameAr) : category;\n\n  // The parts of the chosen section, for the Part dropdown.\n  const [parts, setParts] = useState<{ category: string; list: CategoryPart[] } | null>(null);\n  useEffect(() => {\n    if (!category) return;\n    let current = true;\n    fetchPartsForCategory(category).then((list) => { if (current) setParts({ category, list }); }).catch(() => { if (current) setParts({ category, list: [] }); });\n    return () => { current = false; };\n  }, [category]);\n  const sectionParts = parts?.category === category ? parts.list : null;\n  const partInfo = sectionParts?.find((p) => p.nameEn === part);\n  const partName = partInfo ? pickName(lang, partInfo.nameEn, partInfo.nameAr) : part;\n\n  // A click outside the bar, or Escape, closes the open dropdown.\n  useEffect(() => {\n    if (!open) return;\n    const onDown = (e: MouseEvent) => { if (!(e.target as Element).closest?.(`[data-drop=\"${open}\"]`)) setOpen(null); };\n    const onKey = (e: KeyboardEvent) => { if (e.key === \"Escape\") setOpen(null); };\n    document.addEventListener(\"mousedown\", onDown);\n    document.addEventListener(\"keydown\", onKey);\n    return () => { document.removeEventListener(\"mousedown\", onDown); document.removeEventListener(\"keydown\", onKey); };\n  }, [open]);\n\n  // ---- The car, step by step. The address holds brandId, then modelId, then year (and the generation when only one was made that year). A car that arrives as a\n  // generation only (the garage car, an old link) is looked up once, so its brand and model show in the dropdowns.\n  const generationId = params.get(\"generationId\") ?? \"\";\n  const yearParam = Number(params.get(\"year\")) || null;\n  const modelParam = params.get(\"modelId\") ?? \"\";\n  const [genInfo, setGenInfo] = useState<(VehicleGeneration & { brandId: string }) | null>(null);\n  useEffect(() => {\n    if (!generationId || modelParam) return;\n    let current = true;\n    fetchGeneration(generationId).then((g) => { if (current) setGenInfo(g); }).catch(() => {});\n    return () => { current = false; };\n  }, [generationId, modelParam]);\n  const looked = genInfo?.id === generationId ? genInfo : null;\n  const carBrand = params.get(\"brandId\") || looked?.brandId || \"\";\n  const carModel = params.get(\"modelId\") || looked?.modelId || \"\";\n\n  const [brands, setBrands] = useState<VehicleBrand[] | null>(null);\n  useEffect(() => { let current = true; fetchVehicleBrands().then((b) => { if (current) setBrands(b); }).catch(() => { if (current) setBrands([]); }); return () => { current = false; }; }, []);\n  const [models, setModels] = useState<{ brand: string; list: VehicleModel[] } | null>(null);\n  useEffect(() => {\n    if (!carBrand) return;\n    let current = true;\n    fetchModelsForBrand(carBrand).then((list) => { if (current) setModels({ brand: carBrand, list }); }).catch(() => { if (current) setModels({ brand: carBrand, list: [] }); });\n    return () => { current = false; };\n  }, [carBrand]);\n  const [gens, setGens] = useState<{ model: string; list: VehicleGeneration[] } | null>(null);\n  useEffect(() => {\n    if (!carModel) return;\n    let current = true;\n    fetchGenerationsForModel(carModel).then((list) => { if (current) setGens({ model: carModel, list }); }).catch(() => { if (current) setGens({ model: carModel, list: [] }); });\n    return () => { current = false; };\n  }, [carModel]);\n  const brandModels = models?.brand === carBrand ? models.list : null;\n  const modelGens = gens?.model === carModel ? gens.list : null;\n  const years = modelGens ? modelYears(modelGens) : [];\n  const thisYear = new Date().getFullYear();\n  const gensOfYear = yearParam && modelGens ? modelGens.filter((g) => yearParam >= g.yearStart && yearParam <= (g.yearEnd ?? thisYear)) : [];\n  const brandInfo = brands?.find((b) => b.id === carBrand);\n  const modelInfo = brandModels?.find((m) => m.id === carModel);\n  const brandName = brandInfo ? pickName(lang, brandInfo.name, brandInfo.nameAr) : \"\";\n  const modelName = modelInfo ? pickName(lang, modelInfo.name, modelInfo.nameAr) : \"\";\n  const genName = modelGens?.find((g) => g.id === generationId)?.name ?? \"\";\n  const [brandQuery, setBrandQuery] = useState(\"\");\n  const shownBrands = (brands ?? []).filter((b) => !brandQuery.trim() || `${b.name} ${b.nameAr ?? \"\"}`.toLowerCase().includes(brandQuery.trim().toLowerCase()));\n  const chooseYear = (y: number) => {\n    const fitting = (modelGens ?? []).filter((g) => y >= g.yearStart && y <= (g.yearEnd ?? thisYear));\n    go({ ...noCar(), brandId: carBrand, modelId: carModel, year: y, generationId: fitting.length === 1 ? fitting[0].id : null });   // one generation that year: it is the car\n  };\n\n  const go = (change: Record<string, string | number | null>) => { setOpen(null); router.push(filterHref(params, change)); };\n\n  // Price: typed in the buyer's currency, kept in the address in dollars.\n  const shown = (usd: number | undefined) => (usd === undefined ? \"\" : String(Math.round(usd * rate)));\n  const [minText, setMinText] = useState(shown(extra.minPrice));\n  const [maxText, setMaxText] = useState(shown(extra.maxPrice));\n  useEffect(() => { if (open === \"price\") { setMinText(shown(extra.minPrice)); setMaxText(shown(extra.maxPrice)); } }, [open]);   // eslint-disable-line react-hooks/exhaustive-deps\n  const [p1, p2, p3] = pricePresets(rate);\n  const money = (amount: number) => format(toUsd(amount, rate));\n  const presets: Array<{ label: string; min: number | null; max: number | null }> = [\n    { label: t(\"sf_price_under\", { a: money(p1) }), min: null, max: p1 },\n    { label: t(\"sf_price_between\", { a: money(p1), b: money(p2) }), min: p1, max: p2 },\n    { label: t(\"sf_price_between\", { a: money(p2), b: money(p3) }), min: p2, max: p3 },\n    { label: t(\"sf_price_over\", { a: money(p3) }), min: p3, max: null },\n  ];\n  const priceText = extra.minPrice !== undefined && extra.maxPrice !== undefined ? t(\"sf_price_between\", { a: format(extra.minPrice), b: format(extra.maxPrice) })\n    : extra.maxPrice !== undefined ? t(\"sf_price_up_to\", { a: format(extra.maxPrice) })\n    : extra.minPrice !== undefined ? t(\"sf_price_from\", { a: format(extra.minPrice) }) : null;\n  const applyPrice = () => {\n    const min = Number(minText); const max = Number(maxText);\n    const minUsd = minText.trim() && min > 0 ? toUsd(min, rate) : null;\n    let maxUsd = maxText.trim() && max > 0 ? toUsd(max, rate) : null;\n    if (minUsd !== null && maxUsd !== null && maxUsd < minUsd) maxUsd = null;\n    go({ minPrice: minUsd, maxPrice: maxUsd });\n  };\n\n  const deliveryText = extra.maxDeliveryDays ? t(\"sf_delivery_within\", { n: extra.maxDeliveryDays }) : null;\n  const sorts: Array<[string, DictKey]> = [[\"\", \"sf_sort_best\"], [\"newest\", \"sf_sort_newest\"], [\"price_asc\", \"sf_sort_price_asc\"], [\"price_desc\", \"sf_sort_price_desc\"]];\n  const sortKey = (sorts.find(([v]) => v === (extra.sort ?? \"\")) ?? sorts[0])[1];\n\n  const chips: Array<{ key: string; label: string; change: Record<string, null> }> = [];\n  const carLabel = [brandName, modelName, yearParam ? String(yearParam) : \"\"].filter(Boolean).join(\" \");\n  if (carBrand && carLabel) chips.push({ key: \"car\", label: carLabel, change: noCar() });\n  if (q) chips.push({ key: \"q\", label: `“${q}”`, change: { q: null } });\n  if (category) chips.push({ key: \"category\", label: sectionName, change: { category: null, part: null } });\n  if (part) chips.push({ key: \"part\", label: partName, change: { part: null } });\n  if (priceText) chips.push({ key: \"price\", label: priceText, change: { minPrice: null, maxPrice: null } });\n  if (deliveryText) chips.push({ key: \"delivery\", label: deliveryText, change: { maxDeliveryDays: null } });\n  const clearAll = { ...noCar(), q: null, category: null, part: null, minPrice: null, maxPrice: null, maxDeliveryDays: null, sort: null };\n\n  return (\n    <div ref={root} className=\"mb-2 sm:mb-6\">\n      {/* On a phone the title is not shown: only \"Parts Fit with my Car\" (when there is a garage car), at the very top. */}\n      <div className=\"flex flex-wrap items-end justify-between gap-4 sm:mb-4\">\n        <div className=\"min-w-0 max-sm:hidden\">{heading}</div>\n        <div className=\"empty:hidden max-sm:mb-2 max-sm:w-full sm:min-w-64\"><FitsMyCarToggle /></div>\n      </div>\n\n      {/* On a tablet or a PC one box of two lines; on a phone three boxes, 8 px apart: the car, then section and part, then price, delivery and sort. */}\n      <div className=\"max-sm:grid max-sm:gap-2 sm:rounded-xl sm:border sm:border-line sm:bg-white\">\n      {/* Line 1: the car. Each step filters the results at once. */}\n      <div role=\"group\" aria-label={t(\"sf_your_car\")} className=\"relative flex flex-wrap items-center gap-2 border-line p-2 max-sm:rounded-xl max-sm:border max-sm:bg-white sm:border-b sm:p-2.5\">\n        <span className=\"px-1 text-sm font-bold text-navy max-sm:w-full\">{t(\"sf_your_car\")}</span>\n        <Drop id=\"brand\" label={t(\"sf_brand\")} value={brandName || (carBrand ? \"…\" : t(\"sf_all_brands\"))} active={!!carBrand} open={open} setOpen={(v) => { setOpen(v); setBrandQuery(\"\"); }}>\n          {(brands?.length ?? 0) > 8 && (\n            <input value={brandQuery} onChange={(e) => setBrandQuery(e.target.value)} placeholder={t(\"sf_search_brands\")} aria-label={t(\"sf_search_brands\")} autoFocus className=\"mb-2 w-full rounded-lg border-[1.5px] border-[#c5d0d8] px-2.5 py-2 text-sm\" />\n          )}\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!carBrand)} onClick={() => go(noCar())}><Radio on={!carBrand} />{t(\"sf_all_brands\")}</button>\n            {brands === null ? <p className=\"px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : shownBrands.map((b) => (\n              <button key={b.id} type=\"button\" className={optionRow(b.id === carBrand)} onClick={() => go({ ...noCar(), brandId: b.id })}><Radio on={b.id === carBrand} />{pickName(lang, b.name, b.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"model\" label={t(\"sf_model\")} value={modelName || (carModel ? \"…\" : carBrand ? t(\"sf_all_models\") : t(\"sf_pick_brand_first\"))} active={!!carModel} open={open} setOpen={setOpen} disabled={!carBrand} phoneHidden={!carBrand}>\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!carModel)} onClick={() => go({ ...noCar(), brandId: carBrand })}><Radio on={!carModel} />{t(\"sf_all_models\")}</button>\n            {brandModels === null ? <p className=\"px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : brandModels.map((m) => (\n              <button key={m.id} type=\"button\" className={optionRow(m.id === carModel)} onClick={() => go({ ...noCar(), brandId: carBrand, modelId: m.id })}><Radio on={m.id === carModel} />{pickName(lang, m.name, m.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"year\" label={t(\"sf_year\")} value={yearParam ? String(yearParam) : carModel ? t(\"sf_all_years\") : t(\"sf_pick_model_first\")} active={!!yearParam} open={open} setOpen={setOpen} disabled={!carModel} phoneHidden={!carModel}>\n          <div className=\"grid max-h-80 grid-cols-3 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={`${optionRow(!yearParam)} col-span-3`} onClick={() => go({ ...noCar(), brandId: carBrand, modelId: carModel })}><Radio on={!yearParam} />{t(\"sf_all_years\")}</button>\n            {modelGens === null ? <p className=\"col-span-3 px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : years.map((y) => (\n              <button key={y} type=\"button\" className={`${optionRow(y === yearParam)} justify-center`} onClick={() => chooseYear(y)}>{y}</button>\n            ))}\n          </div>\n        </Drop>\n        {gensOfYear.length > 1 && (\n          <Drop id=\"generation\" label={t(\"sf_generation\")} value={genName || t(\"sf_any_generation\")} active={!!generationId} open={open} setOpen={setOpen}>\n            <div className=\"grid gap-0.5\">\n              <button type=\"button\" className={optionRow(!generationId)} onClick={() => go({ generationId: null, versionId: null })}><Radio on={!generationId} />{t(\"sf_any_generation\")}</button>\n              {gensOfYear.map((g) => <button key={g.id} type=\"button\" className={optionRow(g.id === generationId)} onClick={() => go({ generationId: g.id, versionId: null })}><Radio on={g.id === generationId} />{g.name}</button>)}\n            </div>\n          </Drop>\n        )}\n      </div>\n\n      {/* Line 2: what kind of part, and how it is listed. */}\n      <div role=\"group\" aria-label={t(\"sf_filters\")} className=\"max-sm:contents sm:flex sm:flex-wrap sm:items-center sm:gap-2 sm:p-2.5\">\n        <div className=\"max-sm:relative max-sm:flex max-sm:flex-wrap max-sm:gap-2 max-sm:rounded-xl max-sm:border max-sm:border-line max-sm:bg-white max-sm:p-2 sm:contents\">\n        <Drop id=\"section\" label={t(\"sf_section\")} value={category ? sectionName : t(\"all_sections\")} active={!!category} open={open} setOpen={setOpen}>\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!category)} onClick={() => go({ category: null, part: null })}><Radio on={!category} />{t(\"all_sections\")}</button>\n            {sections.map((s) => (\n              <button key={s.id} type=\"button\" className={optionRow(s.id === category)} onClick={() => go({ category: s.id, part: null })}><Radio on={s.id === category} />{pickName(lang, s.nameEn, s.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"part\" label={t(\"sf_part\")} value={part ? partName : category ? t(\"sf_all_parts\") : t(\"sf_pick_section_first\")} active={!!part} open={open} setOpen={setOpen} disabled={!category} phoneHidden={!category}>\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!part)} onClick={() => go({ part: null })}><Radio on={!part} />{t(\"sf_all_parts\")}</button>\n            {sectionParts === null ? <p className=\"px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : sectionParts.map((p) => (\n              <button key={p.id} type=\"button\" className={optionRow(p.nameEn === part)} onClick={() => go({ part: p.nameEn })}><Radio on={p.nameEn === part} />{pickName(lang, p.nameEn, p.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        </div>\n        <div className=\"max-sm:relative max-sm:grid max-sm:grid-cols-3 max-sm:gap-1.5 max-sm:rounded-xl max-sm:border max-sm:border-line max-sm:bg-white max-sm:p-2 sm:contents\">\n        <Drop id=\"price\" label={t(\"sf_price\")} value={priceText ?? t(\"sf_any_price\")} active={!!priceText} open={open} setOpen={setOpen} stack>\n          <form onSubmit={(e) => { e.preventDefault(); applyPrice(); }} className=\"grid gap-2\">\n            <div className=\"flex gap-2\">\n              <label className=\"min-w-0 flex-1\"><span className=\"sr-only\">{t(\"sf_min\")}</span><input inputMode=\"numeric\" value={minText} onChange={(e) => setMinText(e.target.value.replace(/[^\\d]/g, \"\"))} placeholder={t(\"sf_min\")} className=\"w-full rounded-lg border-[1.5px] border-[#c5d0d8] px-2.5 py-2 text-sm\" /></label>\n              <label className=\"min-w-0 flex-1\"><span className=\"sr-only\">{t(\"sf_max\")}</span><input inputMode=\"numeric\" value={maxText} onChange={(e) => setMaxText(e.target.value.replace(/[^\\d]/g, \"\"))} placeholder={t(\"sf_max\")} className=\"w-full rounded-lg border-[1.5px] border-[#c5d0d8] px-2.5 py-2 text-sm\" /></label>\n            </div>\n            <div className=\"grid gap-0.5\">\n              {presets.map((p) => {\n                const on = (p.min === null ? extra.minPrice === undefined : extra.minPrice === toUsd(p.min, rate)) && (p.max === null ? extra.maxPrice === undefined : extra.maxPrice === toUsd(p.max, rate));\n                return <button key={p.label} type=\"button\" className={optionRow(on)} onClick={() => go({ minPrice: p.min === null ? null : toUsd(p.min, rate), maxPrice: p.max === null ? null : toUsd(p.max, rate) })}><Radio on={on} />{p.label}</button>;\n              })}\n            </div>\n            <div className=\"flex gap-2\">\n              <button type=\"submit\" className=\"inline-flex min-h-10 flex-1 items-center justify-center rounded-[10px] bg-signal px-4 text-sm font-bold text-on-signal hover:bg-signal-dark\">{t(\"sf_show_results\")}</button>\n              {priceText && <button type=\"button\" onClick={() => go({ minPrice: null, maxPrice: null })} className=\"min-h-10 px-2 text-sm font-semibold text-navy underline underline-offset-4\">{t(\"clear\")}</button>}\n            </div>\n          </form>\n        </Drop>\n        <Drop id=\"delivery\" label={t(\"sf_delivery\")} value={deliveryText ?? t(\"sf_delivery_any\")} active={!!deliveryText} open={open} setOpen={setOpen} stack>\n          <div className=\"grid gap-0.5\">\n            <button type=\"button\" className={optionRow(!extra.maxDeliveryDays)} onClick={() => go({ maxDeliveryDays: null })}><Radio on={!extra.maxDeliveryDays} />{t(\"sf_delivery_any\")}</button>\n            {DELIVERY_DAYS.map((d) => <button key={d} type=\"button\" className={optionRow(extra.maxDeliveryDays === d)} onClick={() => go({ maxDeliveryDays: d })}><Radio on={extra.maxDeliveryDays === d} />{t(\"sf_delivery_within\", { n: d })}</button>)}\n          </div>\n        </Drop>\n        <div className=\"min-w-0 sm:ms-auto\">\n          <Drop id=\"sort\" label={t(\"sf_sort\")} value={t(sortKey)} active={!!extra.sort} open={open} setOpen={setOpen} alignEnd stack>\n            <div className=\"grid gap-0.5\">\n              {sorts.map(([v, key]) => <button key={key} type=\"button\" className={optionRow((extra.sort ?? \"\") === v)} onClick={() => go({ sort: v || null })}><Radio on={(extra.sort ?? \"\") === v} />{t(key)}</button>)}\n            </div>\n          </Drop>\n        </div>\n        </div>\n      </div>\n      </div>\n\n      <div className=\"mt-2 flex flex-wrap items-center gap-2 sm:mt-3\">\n        {chips.map((c) => (\n          <button key={c.key} type=\"button\" onClick={() => go(c.change)} className={chip}>\n            <span className=\"max-w-[16rem] truncate\">{c.label}</span><span aria-hidden=\"true\" className=\"opacity-80\">×</span><span className=\"sr-only\">{t(\"clear\")}</span>\n          </button>\n        ))}\n        {chips.length > 1 && <button type=\"button\" onClick={() => go(clearAll)} className=\"min-h-8 px-1 text-sm font-bold text-navy underline underline-offset-4\">{t(\"sf_clear_all\")}</button>}\n        <span className=\"ms-auto\" />\n        <SaveSearchButton searchTerm={q || undefined} category={category || undefined} />\n      </div>\n    </div>\n  );\n}\n"], "text": "\"use client\";\n\nimport { useEffect, useRef, useState } from \"react\";\nimport { useSearchParams } from \"next/navigation\";\nimport { fetchGeneration, fetchGenerationsForModel, fetchModelsForBrand, fetchPartsForCategory, fetchVehicleBrands, type CategoryPart, type VehicleBrand, type VehicleGeneration, type VehicleModel } from \"@/lib/api\";\nimport { pickName, type DictKey } from \"@/lib/i18n\";\nimport { DELIVERY_DAYS, filterHref, modelYears, noCar, pricePresets, readExtraFilters, toUsd } from \"@/lib/searchFilters\";\nimport { useCurrency } from \"./CurrencyProvider\";\nimport FitsMyCarToggle from \"./FitsMyCarToggle\";\nimport { useLang, useT } from \"./LangProvider\";\nimport { SaveSearchButton } from \"./SaveSearchButton\";\nimport { useLocRouter } from \"./useLocRouter\";\n\nexport interface FilterSection { id: string; nameEn: string; nameAr: string | null }\n\nconst pill = \"inline-flex min-h-10 items-center gap-1.5 whitespace-nowrap rounded-[10px] border-[1.5px] px-3 text-sm font-semibold\";\nconst chip = \"inline-flex min-h-8 items-center gap-2 rounded-full bg-navy px-3 text-xs font-bold text-white hover:bg-[#123f56]\";\nconst pop = \"absolute start-0 top-full z-30 mt-2 w-72 rounded-xl border border-[#c5d0d8] bg-white p-3 shadow-[0_12px_30px_rgba(10,49,68,0.18)]\";\nconst optionRow = (on: boolean) => `flex min-h-10 w-full items-center gap-2.5 rounded-lg px-2 text-start text-sm ${on ? \"bg-[#f4f8fb] font-bold text-navy\" : \"hover:bg-chalk\"}`;\n\nfunction Radio({ on }: { on: boolean }) {\n  return <span aria-hidden=\"true\" className={`size-4 flex-none rounded-full border-2 ${on ? \"border-[5px] border-navy\" : \"border-[#8696a2]\"}`} />;\n}\n\n/** One dropdown of the bar: a button showing \"Label: value\", and its panel. Only one is open at a time; a click outside or Escape closes it. */\n// On a phone: phoneHidden hides a step until the one before it is chosen; the label (\"Brand:\") is not shown, only the value (screen readers still read it);\n// stack makes the button fill its column, so three fit on one line.\n// Every panel opens under its box, as wide as the box (the box is the one positioned on a phone), so it never runs off the screen.\nfunction Drop({ id, label, value, active, open, setOpen, disabled, alignEnd, phoneHidden, stack, children }: {\n  id: string; label: string; value: string; active: boolean; open: string | null; setOpen: (v: string | null) => void; disabled?: boolean; alignEnd?: boolean; phoneHidden?: boolean; stack?: boolean; children: React.ReactNode;\n}) {\n  const isOpen = open === id;\n  return (\n    <div className={`relative max-sm:static ${stack ? \"min-w-0\" : \"\"} ${phoneHidden ? \"max-sm:hidden\" : \"\"}`} data-drop={id}>\n      <button type=\"button\" aria-haspopup=\"true\" aria-expanded={isOpen} disabled={disabled} onClick={() => setOpen(isOpen ? null : id)}\n        className={`${pill} ${stack ? \"max-sm:w-full max-sm:justify-center max-sm:gap-1 max-sm:px-1 max-sm:text-[13px]\" : \"\"} ${active ? \"border-navy bg-[#f4f8fb] text-ink\" : \"border-[#c5d0d8] bg-white text-ink\"} disabled:cursor-not-allowed disabled:opacity-50`}>\n        <span className=\"font-medium text-muted max-sm:sr-only\">{label}:</span><span className={`max-w-[12rem] truncate ${stack ? \"max-sm:min-w-0\" : \"\"}`}>{value}</span>\n        <svg aria-hidden=\"true\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" className={`flex-none text-muted transition-transform ${isOpen ? \"rotate-180\" : \"\"}`}><path d=\"M6 9l6 6 6-6\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.4\" strokeLinecap=\"round\" strokeLinejoin=\"round\" /></svg>\n      </button>\n      {isOpen && <div role=\"dialog\" aria-label={label} className={`${pop} ${alignEnd ? \"sm:start-auto sm:end-0\" : \"\"} max-sm:inset-x-0 max-sm:w-auto`}>{children}</div>}\n    </div>\n  );\n}\n\n/**\n * The filters of the results page, all in one place: the title with the \"Fits my car\" switch, then one box of dropdowns. Its first line is the car, chosen step by\n * step and filtering at EVERY step (a brand shows all its parts, then a model narrows to that model, then a year to that year); its second line is the section, the\n * part, the price, the delivery and the sort. Then the filters that are on, then the filters that are on as chips (each removed with its ×, or all with \"Clear all\") and \"Save this search\". The title and the number of parts come from the page.\n * Every choice is a new address (/search?...), so the server draws the filtered page and each filtered page has its own link.\n */\nexport function SearchFilters({ sections, heading }: { sections: FilterSection[]; heading?: React.ReactNode }) {\n  const params = useSearchParams();\n  const router = useLocRouter();\n  const lang = useLang();\n  const t = useT();\n  const { format, rate } = useCurrency();\n  const [open, setOpen] = useState<string | null>(null);\n  const root = useRef<HTMLDivElement>(null);\n\n  const q = params.get(\"q\") ?? \"\";\n  const category = params.get(\"category\") ?? \"\";\n  const part = params.get(\"part\") ?? \"\";\n  const extra = readExtraFilters((n) => params.get(n));\n  const section = sections.find((s) => s.id === category) ?? null;\n  const sectionName = section ? pickName(lang, section.nameEn, section.nameAr) : category;\n\n  // The parts of the chosen section, for the Part dropdown.\n  const [parts, setParts] = useState<{ category: string; list: CategoryPart[] } | null>(null);\n  useEffect(() => {\n    if (!category) return;\n    let current = true;\n    fetchPartsForCategory(category).then((list) => { if (current) setParts({ category, list }); }).catch(() => { if (current) setParts({ category, list: [] }); });\n    return () => { current = false; };\n  }, [category]);\n  const sectionParts = parts?.category === category ? parts.list : null;\n  const partInfo = sectionParts?.find((p) => p.nameEn === part);\n  const partName = partInfo ? pickName(lang, partInfo.nameEn, partInfo.nameAr) : part;\n\n  // A click outside the bar, or Escape, closes the open dropdown.\n  useEffect(() => {\n    if (!open) return;\n    const onDown = (e: MouseEvent) => { if (!(e.target as Element).closest?.(`[data-drop=\"${open}\"]`)) setOpen(null); };\n    const onKey = (e: KeyboardEvent) => { if (e.key === \"Escape\") setOpen(null); };\n    document.addEventListener(\"mousedown\", onDown);\n    document.addEventListener(\"keydown\", onKey);\n    return () => { document.removeEventListener(\"mousedown\", onDown); document.removeEventListener(\"keydown\", onKey); };\n  }, [open]);\n\n  // ---- The car, step by step. The address holds brandId, then modelId, then year (and the generation when only one was made that year). A car that arrives as a\n  // generation only (the garage car, an old link) is looked up once, so its brand and model show in the dropdowns.\n  const generationId = params.get(\"generationId\") ?? \"\";\n  const yearParam = Number(params.get(\"year\")) || null;\n  const modelParam = params.get(\"modelId\") ?? \"\";\n  const [genInfo, setGenInfo] = useState<(VehicleGeneration & { brandId: string }) | null>(null);\n  useEffect(() => {\n    if (!generationId || modelParam) return;\n    let current = true;\n    fetchGeneration(generationId).then((g) => { if (current) setGenInfo(g); }).catch(() => {});\n    return () => { current = false; };\n  }, [generationId, modelParam]);\n  const looked = genInfo?.id === generationId ? genInfo : null;\n  const carBrand = params.get(\"brandId\") || looked?.brandId || \"\";\n  const carModel = params.get(\"modelId\") || looked?.modelId || \"\";\n\n  const [brands, setBrands] = useState<VehicleBrand[] | null>(null);\n  useEffect(() => { let current = true; fetchVehicleBrands().then((b) => { if (current) setBrands(b); }).catch(() => { if (current) setBrands([]); }); return () => { current = false; }; }, []);\n  const [models, setModels] = useState<{ brand: string; list: VehicleModel[] } | null>(null);\n  useEffect(() => {\n    if (!carBrand) return;\n    let current = true;\n    fetchModelsForBrand(carBrand).then((list) => { if (current) setModels({ brand: carBrand, list }); }).catch(() => { if (current) setModels({ brand: carBrand, list: [] }); });\n    return () => { current = false; };\n  }, [carBrand]);\n  const [gens, setGens] = useState<{ model: string; list: VehicleGeneration[] } | null>(null);\n  useEffect(() => {\n    if (!carModel) return;\n    let current = true;\n    fetchGenerationsForModel(carModel).then((list) => { if (current) setGens({ model: carModel, list }); }).catch(() => { if (current) setGens({ model: carModel, list: [] }); });\n    return () => { current = false; };\n  }, [carModel]);\n  const brandModels = models?.brand === carBrand ? models.list : null;\n  const modelGens = gens?.model === carModel ? gens.list : null;\n  const years = modelGens ? modelYears(modelGens) : [];\n  const thisYear = new Date().getFullYear();\n  const gensOfYear = yearParam && modelGens ? modelGens.filter((g) => yearParam >= g.yearStart && yearParam <= (g.yearEnd ?? thisYear)) : [];\n  const brandInfo = brands?.find((b) => b.id === carBrand);\n  const modelInfo = brandModels?.find((m) => m.id === carModel);\n  const brandName = brandInfo ? pickName(lang, brandInfo.name, brandInfo.nameAr) : \"\";\n  const modelName = modelInfo ? pickName(lang, modelInfo.name, modelInfo.nameAr) : \"\";\n  const genName = modelGens?.find((g) => g.id === generationId)?.name ?? \"\";\n  const [brandQuery, setBrandQuery] = useState(\"\");\n  const shownBrands = (brands ?? []).filter((b) => !brandQuery.trim() || `${b.name} ${b.nameAr ?? \"\"}`.toLowerCase().includes(brandQuery.trim().toLowerCase()));\n  const chooseYear = (y: number) => {\n    const fitting = (modelGens ?? []).filter((g) => y >= g.yearStart && y <= (g.yearEnd ?? thisYear));\n    go({ ...noCar(), brandId: carBrand, modelId: carModel, year: y, generationId: fitting.length === 1 ? fitting[0].id : null });   // one generation that year: it is the car\n  };\n\n  const go = (change: Record<string, string | number | null>) => { setOpen(null); router.push(filterHref(params, change)); };\n\n  // Price: typed in the buyer's currency, kept in the address in dollars.\n  const shown = (usd: number | undefined) => (usd === undefined ? \"\" : String(Math.round(usd * rate)));\n  const [minText, setMinText] = useState(shown(extra.minPrice));\n  const [maxText, setMaxText] = useState(shown(extra.maxPrice));\n  useEffect(() => { if (open === \"price\") { setMinText(shown(extra.minPrice)); setMaxText(shown(extra.maxPrice)); } }, [open]);   // eslint-disable-line react-hooks/exhaustive-deps\n  const [p1, p2, p3] = pricePresets(rate);\n  const money = (amount: number) => format(toUsd(amount, rate));\n  const presets: Array<{ label: string; min: number | null; max: number | null }> = [\n    { label: t(\"sf_price_under\", { a: money(p1) }), min: null, max: p1 },\n    { label: t(\"sf_price_between\", { a: money(p1), b: money(p2) }), min: p1, max: p2 },\n    { label: t(\"sf_price_between\", { a: money(p2), b: money(p3) }), min: p2, max: p3 },\n    { label: t(\"sf_price_over\", { a: money(p3) }), min: p3, max: null },\n  ];\n  const priceText = extra.minPrice !== undefined && extra.maxPrice !== undefined ? t(\"sf_price_between\", { a: format(extra.minPrice), b: format(extra.maxPrice) })\n    : extra.maxPrice !== undefined ? t(\"sf_price_up_to\", { a: format(extra.maxPrice) })\n    : extra.minPrice !== undefined ? t(\"sf_price_from\", { a: format(extra.minPrice) }) : null;\n  const applyPrice = () => {\n    const min = Number(minText); const max = Number(maxText);\n    const minUsd = minText.trim() && min > 0 ? toUsd(min, rate) : null;\n    let maxUsd = maxText.trim() && max > 0 ? toUsd(max, rate) : null;\n    if (minUsd !== null && maxUsd !== null && maxUsd < minUsd) maxUsd = null;\n    go({ minPrice: minUsd, maxPrice: maxUsd });\n  };\n\n  const deliveryText = extra.maxDeliveryDays ? t(\"sf_delivery_within\", { n: extra.maxDeliveryDays }) : null;\n  const sorts: Array<[string, DictKey]> = [[\"\", \"sf_sort_best\"], [\"newest\", \"sf_sort_newest\"], [\"price_asc\", \"sf_sort_price_asc\"], [\"price_desc\", \"sf_sort_price_desc\"]];\n  const sortKey = (sorts.find(([v]) => v === (extra.sort ?? \"\")) ?? sorts[0])[1];\n\n  const chips: Array<{ key: string; label: string; change: Record<string, null> }> = [];\n  const carLabel = [brandName, modelName, yearParam ? String(yearParam) : \"\"].filter(Boolean).join(\" \");\n  if (carBrand && carLabel) chips.push({ key: \"car\", label: carLabel, change: noCar() });\n  if (q) chips.push({ key: \"q\", label: `“${q}”`, change: { q: null } });\n  if (category) chips.push({ key: \"category\", label: sectionName, change: { category: null, part: null } });\n  if (part) chips.push({ key: \"part\", label: partName, change: { part: null } });\n  if (priceText) chips.push({ key: \"price\", label: priceText, change: { minPrice: null, maxPrice: null } });\n  if (deliveryText) chips.push({ key: \"delivery\", label: deliveryText, change: { maxDeliveryDays: null } });\n  const clearAll = { ...noCar(), q: null, category: null, part: null, minPrice: null, maxPrice: null, maxDeliveryDays: null, sort: null };\n\n  return (\n    <div ref={root} className=\"mb-2 sm:mb-6\">\n      {/* On a phone the title is not shown: only \"Parts Fit with my Car\" (when there is a garage car), at the very top. */}\n      <div className=\"flex flex-wrap items-end justify-between gap-4 sm:mb-4\">\n        <div className=\"min-w-0 max-sm:hidden\">{heading}</div>\n        <div className=\"empty:hidden max-sm:mb-2 max-sm:w-full sm:min-w-64\"><FitsMyCarToggle /></div>\n      </div>\n\n      {/* On a tablet or a PC one box of two lines; on a phone three boxes, 8 px apart, with no titles: the car, then section and part, then price, delivery and sort. */}\n      <div className=\"max-sm:grid max-sm:gap-2 sm:rounded-xl sm:border sm:border-line sm:bg-white\">\n      {/* Line 1: the car. Each step filters the results at once. */}\n      <div role=\"group\" aria-label={t(\"sf_your_car\")} className=\"relative flex flex-wrap items-center gap-2 border-line p-2 max-sm:rounded-xl max-sm:border max-sm:bg-white sm:border-b sm:p-2.5\">\n        <span className=\"px-1 text-sm font-bold text-navy max-sm:sr-only\">{t(\"sf_your_car\")}</span>          {/* on a phone no title: the buttons say it */}\n        <Drop id=\"brand\" label={t(\"sf_brand\")} value={brandName || (carBrand ? \"…\" : t(\"sf_all_brands\"))} active={!!carBrand} open={open} setOpen={(v) => { setOpen(v); setBrandQuery(\"\"); }}>\n          {(brands?.length ?? 0) > 8 && (\n            <input value={brandQuery} onChange={(e) => setBrandQuery(e.target.value)} placeholder={t(\"sf_search_brands\")} aria-label={t(\"sf_search_brands\")} autoFocus className=\"mb-2 w-full rounded-lg border-[1.5px] border-[#c5d0d8] px-2.5 py-2 text-sm\" />\n          )}\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!carBrand)} onClick={() => go(noCar())}><Radio on={!carBrand} />{t(\"sf_all_brands\")}</button>\n            {brands === null ? <p className=\"px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : shownBrands.map((b) => (\n              <button key={b.id} type=\"button\" className={optionRow(b.id === carBrand)} onClick={() => go({ ...noCar(), brandId: b.id })}><Radio on={b.id === carBrand} />{pickName(lang, b.name, b.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"model\" label={t(\"sf_model\")} value={modelName || (carModel ? \"…\" : carBrand ? t(\"sf_all_models\") : t(\"sf_pick_brand_first\"))} active={!!carModel} open={open} setOpen={setOpen} disabled={!carBrand} phoneHidden={!carBrand}>\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!carModel)} onClick={() => go({ ...noCar(), brandId: carBrand })}><Radio on={!carModel} />{t(\"sf_all_models\")}</button>\n            {brandModels === null ? <p className=\"px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : brandModels.map((m) => (\n              <button key={m.id} type=\"button\" className={optionRow(m.id === carModel)} onClick={() => go({ ...noCar(), brandId: carBrand, modelId: m.id })}><Radio on={m.id === carModel} />{pickName(lang, m.name, m.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"year\" label={t(\"sf_year\")} value={yearParam ? String(yearParam) : carModel ? t(\"sf_all_years\") : t(\"sf_pick_model_first\")} active={!!yearParam} open={open} setOpen={setOpen} disabled={!carModel} phoneHidden={!carModel}>\n          <div className=\"grid max-h-80 grid-cols-3 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={`${optionRow(!yearParam)} col-span-3`} onClick={() => go({ ...noCar(), brandId: carBrand, modelId: carModel })}><Radio on={!yearParam} />{t(\"sf_all_years\")}</button>\n            {modelGens === null ? <p className=\"col-span-3 px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : years.map((y) => (\n              <button key={y} type=\"button\" className={`${optionRow(y === yearParam)} justify-center`} onClick={() => chooseYear(y)}>{y}</button>\n            ))}\n          </div>\n        </Drop>\n        {gensOfYear.length > 1 && (\n          <Drop id=\"generation\" label={t(\"sf_generation\")} value={genName || t(\"sf_any_generation\")} active={!!generationId} open={open} setOpen={setOpen}>\n            <div className=\"grid gap-0.5\">\n              <button type=\"button\" className={optionRow(!generationId)} onClick={() => go({ generationId: null, versionId: null })}><Radio on={!generationId} />{t(\"sf_any_generation\")}</button>\n              {gensOfYear.map((g) => <button key={g.id} type=\"button\" className={optionRow(g.id === generationId)} onClick={() => go({ generationId: g.id, versionId: null })}><Radio on={g.id === generationId} />{g.name}</button>)}\n            </div>\n          </Drop>\n        )}\n      </div>\n\n      {/* Line 2: what kind of part, and how it is listed. */}\n      <div role=\"group\" aria-label={t(\"sf_filters\")} className=\"max-sm:contents sm:flex sm:flex-wrap sm:items-center sm:gap-2 sm:p-2.5\">\n        <div className=\"max-sm:relative max-sm:flex max-sm:flex-wrap max-sm:gap-2 max-sm:rounded-xl max-sm:border max-sm:border-line max-sm:bg-white max-sm:p-2 sm:contents\">\n        <Drop id=\"section\" label={t(\"sf_section\")} value={category ? sectionName : t(\"all_sections\")} active={!!category} open={open} setOpen={setOpen}>\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!category)} onClick={() => go({ category: null, part: null })}><Radio on={!category} />{t(\"all_sections\")}</button>\n            {sections.map((s) => (\n              <button key={s.id} type=\"button\" className={optionRow(s.id === category)} onClick={() => go({ category: s.id, part: null })}><Radio on={s.id === category} />{pickName(lang, s.nameEn, s.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        <Drop id=\"part\" label={t(\"sf_part\")} value={part ? partName : category ? t(\"sf_all_parts\") : t(\"sf_pick_section_first\")} active={!!part} open={open} setOpen={setOpen} disabled={!category} phoneHidden={!category}>\n          <div className=\"grid max-h-80 gap-0.5 overflow-y-auto\">\n            <button type=\"button\" className={optionRow(!part)} onClick={() => go({ part: null })}><Radio on={!part} />{t(\"sf_all_parts\")}</button>\n            {sectionParts === null ? <p className=\"px-2 py-2 text-sm text-muted\">{t(\"search_loading\")}</p> : sectionParts.map((p) => (\n              <button key={p.id} type=\"button\" className={optionRow(p.nameEn === part)} onClick={() => go({ part: p.nameEn })}><Radio on={p.nameEn === part} />{pickName(lang, p.nameEn, p.nameAr)}</button>\n            ))}\n          </div>\n        </Drop>\n        </div>\n        <div className=\"max-sm:relative max-sm:grid max-sm:grid-cols-3 max-sm:gap-1.5 max-sm:rounded-xl max-sm:border max-sm:border-line max-sm:bg-white max-sm:p-2 sm:contents\">\n        <Drop id=\"price\" label={t(\"sf_price\")} value={priceText ?? t(\"sf_any_price\")} active={!!priceText} open={open} setOpen={setOpen} stack>\n          <form onSubmit={(e) => { e.preventDefault(); applyPrice(); }} className=\"grid gap-2\">\n            <div className=\"flex gap-2\">\n              <label className=\"min-w-0 flex-1\"><span className=\"sr-only\">{t(\"sf_min\")}</span><input inputMode=\"numeric\" value={minText} onChange={(e) => setMinText(e.target.value.replace(/[^\\d]/g, \"\"))} placeholder={t(\"sf_min\")} className=\"w-full rounded-lg border-[1.5px] border-[#c5d0d8] px-2.5 py-2 text-sm\" /></label>\n              <label className=\"min-w-0 flex-1\"><span className=\"sr-only\">{t(\"sf_max\")}</span><input inputMode=\"numeric\" value={maxText} onChange={(e) => setMaxText(e.target.value.replace(/[^\\d]/g, \"\"))} placeholder={t(\"sf_max\")} className=\"w-full rounded-lg border-[1.5px] border-[#c5d0d8] px-2.5 py-2 text-sm\" /></label>\n            </div>\n            <div className=\"grid gap-0.5\">\n              {presets.map((p) => {\n                const on = (p.min === null ? extra.minPrice === undefined : extra.minPrice === toUsd(p.min, rate)) && (p.max === null ? extra.maxPrice === undefined : extra.maxPrice === toUsd(p.max, rate));\n                return <button key={p.label} type=\"button\" className={optionRow(on)} onClick={() => go({ minPrice: p.min === null ? null : toUsd(p.min, rate), maxPrice: p.max === null ? null : toUsd(p.max, rate) })}><Radio on={on} />{p.label}</button>;\n              })}\n            </div>\n            <div className=\"flex gap-2\">\n              <button type=\"submit\" className=\"inline-flex min-h-10 flex-1 items-center justify-center rounded-[10px] bg-signal px-4 text-sm font-bold text-on-signal hover:bg-signal-dark\">{t(\"sf_show_results\")}</button>\n              {priceText && <button type=\"button\" onClick={() => go({ minPrice: null, maxPrice: null })} className=\"min-h-10 px-2 text-sm font-semibold text-navy underline underline-offset-4\">{t(\"clear\")}</button>}\n            </div>\n          </form>\n        </Drop>\n        <Drop id=\"delivery\" label={t(\"sf_delivery\")} value={deliveryText ?? t(\"sf_delivery_any\")} active={!!deliveryText} open={open} setOpen={setOpen} stack>\n          <div className=\"grid gap-0.5\">\n            <button type=\"button\" className={optionRow(!extra.maxDeliveryDays)} onClick={() => go({ maxDeliveryDays: null })}><Radio on={!extra.maxDeliveryDays} />{t(\"sf_delivery_any\")}</button>\n            {DELIVERY_DAYS.map((d) => <button key={d} type=\"button\" className={optionRow(extra.maxDeliveryDays === d)} onClick={() => go({ maxDeliveryDays: d })}><Radio on={extra.maxDeliveryDays === d} />{t(\"sf_delivery_within\", { n: d })}</button>)}\n          </div>\n        </Drop>\n        <div className=\"min-w-0 sm:ms-auto\">\n          <Drop id=\"sort\" label={t(\"sf_sort\")} value={t(sortKey)} active={!!extra.sort} open={open} setOpen={setOpen} alignEnd stack>\n            <div className=\"grid gap-0.5\">\n              {sorts.map(([v, key]) => <button key={key} type=\"button\" className={optionRow((extra.sort ?? \"\") === v)} onClick={() => go({ sort: v || null })}><Radio on={(extra.sort ?? \"\") === v} />{t(key)}</button>)}\n            </div>\n          </Drop>\n        </div>\n        </div>\n      </div>\n      </div>\n\n      <div className=\"mt-2 flex flex-wrap items-center gap-2 sm:mt-3\">\n        {chips.map((c) => (\n          <button key={c.key} type=\"button\" onClick={() => go(c.change)} className={chip}>\n            <span className=\"max-w-[16rem] truncate\">{c.label}</span><span aria-hidden=\"true\" className=\"opacity-80\">×</span><span className=\"sr-only\">{t(\"clear\")}</span>\n          </button>\n        ))}\n        {chips.length > 1 && <button type=\"button\" onClick={() => go(clearAll)} className=\"min-h-8 px-1 text-sm font-bold text-navy underline underline-offset-4\">{t(\"sf_clear_all\")}</button>}\n        <span className=\"ms-auto\" />\n        <SaveSearchButton searchTerm={q || undefined} category={category || undefined} />\n      </div>\n    </div>\n  );\n}\n"}, {"file": "apps/web-storefront/app/search/page.tsx", "what": "website search page on a phone: no second search box, no title or count, 8 px gaps", "done": "px-2 pb-8 pt-2 sm:px-6 sm:py-10", "from": ["import { Suspense } from \"react\";\nimport type { Metadata } from \"next\";\nimport Link from \"@/components/LocLink\";\nimport { fetchCategories, fetchPartsForCategory, fetchProductsPaginated, type CategoryPart } from \"@/lib/api\";\nimport InfiniteProductGrid from \"@/components/InfiniteProductGrid\";\nimport { localizePath, pickName, t } from \"@/lib/i18n\";\nimport { getLang } from \"@/lib/lang\";\nimport { SearchFilters } from \"@/components/SearchFilters\";\nimport { filterHref, readExtraFilters } from \"@/lib/searchFilters\";\nimport { alternatesFor, categoryPageDescription, categoryPageTitle, searchIndexing } from \"@/lib/seo\";\n\nconst PAGE_SIZE = 24;\n\ninterface PageProps {\n  searchParams: Promise<{ q?: string; category?: string; part?: string; generationId?: string; year?: string; versionId?: string; brandId?: string; modelId?: string; page?: string; sort?: string; minPrice?: string; maxPrice?: string; maxDeliveryDays?: string }>;\n}\n\nexport async function generateMetadata({\n  searchParams,\n}: PageProps): Promise<Metadata> {\n  const params = await searchParams;\n  const { q, category, part } = params;\n  // A category page is a real landing page: indexed, with its own title. Every other combination (a typed query, a vehicle filter, page 2...) is a variation of\n  // it: followed, but kept out of the index and pointing at the category page as the one real version (see searchIndexing in lib/seo.ts).\n  const lang = await getLang();\n  const { index, canonicalPath } = searchIndexing(params);\n  let title = q ? t(lang, \"search_results_for\", { q }) : t(lang, \"search_all_parts\");\n  let description: string | undefined;\n  if (!q && category) {\n    const found = (await fetchCategories()).find((c) => c.id === category);\n    if (found) {\n      const categoryName = pickName(lang, found.nameEn, found.nameAr);\n      title = part ? `${part} — ${categoryName}` : categoryPageTitle(categoryName, lang);          // a part page is titled by its part\n      description = categoryPageDescription(categoryName, lang);\n    }\n  }\n  return { title, description, alternates: alternatesFor(lang, canonicalPath), robots: { index, follow: true } };\n}\n\n// Real Server Component -- re-fetches real, filtered results on every\n// real navigation (a new search query, category, real vehicle\n// fitment, or page number is a real new page request in this model),\n// so a search engine can index each real filtered result page on its\n// own, with its own real URL.\nexport default async function SearchPage({ searchParams }: PageProps) {\n  const sp = await searchParams;\n  const { q, category, part, generationId, year, versionId, page } = sp;\n  const brandId = sp.brandId && /^[\\w.:\\-]{1,120}$/.test(sp.brandId) ? sp.brandId : undefined;          // the car chosen step by step (brand, then model, then year)\n  const modelId = sp.modelId && /^[\\w.:\\-]{1,120}$/.test(sp.modelId) ? sp.modelId : undefined;\n  const extra = readExtraFilters((n) => sp[n as keyof typeof sp]);          // sort, price range, delivery time (checked; anything odd is ignored)\n  const lang = await getLang();\n  const pageNum = Math.max(Number(page) || 1, 1);\n  const [categories, { items: products, total, unreachable }, sectionParts] = await Promise.all([\n    fetchCategories(),\n    fetchProductsPaginated({ search: q, category, part, generationId, year: year ? Number(year) : undefined, versionId, brandId, modelId, ...extra, page: pageNum, limit: PAGE_SIZE, lang }),\n    part && category ? fetchPartsForCategory(category).catch((): CategoryPart[] => []) : Promise.resolve<CategoryPart[]>([]),          // only for the part's name in the page's language\n  ]);\n  const totalPages = Math.max(Math.ceil(total / PAGE_SIZE), 1);\n  const sectionName = category ? (() => { const c = categories.find((x) => x.id === category); return c ? pickName(lang, c.nameEn, c.nameAr) : category; })() : null;\n  const current = new URLSearchParams(Object.entries(sp).filter((e): e is [string, string] => typeof e[1] === \"string\"));\n  // A link to another page of the SAME results: every filter is kept (search words, section, part, car, sort, price, delivery), only the page changes.\n  const pageHref = (p: number) => {\n    const href = filterHref(current, {});\n    return p > 1 ? `${href}${href.includes(\"?\") ? \"&\" : \"?\"}page=${p}` : href;\n  };\n  // The title says what is being looked at: the part, else the section, else the search words; under it, where, and how many parts (fit the car).\n  const partInfo = part ? sectionParts.find((p) => p.nameEn === part) : undefined;\n  const title = (part && (partInfo ? pickName(lang, partInfo.nameEn, partInfo.nameAr) : part)) || sectionName || (q ? t(lang, \"search_results_for\", { q }) : t(lang, \"search_all_parts\"));\n  const countText = generationId || modelId || brandId\n    ? (total === 1 ? t(lang, \"sf_fit_car_one\") : t(lang, \"sf_fit_car_many\", { n: total }))\n    : (total === 1 ? t(lang, \"parts_found_one\") : t(lang, \"parts_found\", { n: total }));\n  const heading = (\n    <div>\n      <h1 className=\"text-2xl font-extrabold tracking-tight [overflow-wrap:anywhere]\">{title}</h1>\n      <p className=\"mt-1 text-sm text-muted\">{part && sectionName ? `${t(lang, \"sf_in_section\", { section: sectionName })} · ` : \"\"}{countText}</p>\n    </div>\n  );\n\n  return (\n    <div className=\"mx-auto max-w-7xl px-6 py-10\">\n      <form action={localizePath(lang, \"/search\")} className=\"mb-8\">\n        <input\n          type=\"text\"\n          name=\"q\"\n          defaultValue={q}\n          placeholder={t(lang, \"search_page_placeholder\")}\n          className=\"w-full rounded-md border border-line px-4 py-3 text-sm\"\n        />\n      </form>\n\n      {/* The title, the car, ONE bar of filters (section, part, price, delivery, sort) and the filters that are on, as chips: all in one place above the results, which keep\n          four columns. A real <Suspense> boundary is required around useSearchParams() (a production build fails without one); its fallback is the title alone. */}\n      <Suspense fallback={<div className=\"mb-6\">{heading}</div>}>\n        <SearchFilters sections={categories.map((c) => ({ id: c.id, nameEn: c.nameEn, nameAr: c.nameAr }))} heading={heading} />\n      </Suspense>\n      <div className=\"flex flex-col gap-6 lg:flex-row lg:gap-8\">\n        <div className=\"min-w-0 flex-1\">\n          {products.length === 0 ? (\n            <p className=\"text-muted\">\n              {unreachable\n                ? t(lang, \"shop_unreachable\")\n                : generationId || modelId || brandId\n                  ? t(lang, \"no_parts_vehicle\")\n                  : t(lang, \"no_parts_search\")}\n            </p>\n          ) : (\n            <>\n              {pageNum > 1 && <p className=\"mb-4\"><Link href={pageHref(1)} className=\"text-sm font-bold text-navy underline underline-offset-4\">{t(lang, \"grid_back_to_start\")}</Link></p>}\n              {/* The first page is drawn here, on the server (in the page's HTML); the rest loads as the buyer scrolls. The key starts a fresh list whenever the search or a filter changes. */}\n              <InfiniteProductGrid\n                key={`${filterHref(current, {})}|${pageNum}`}\n                id=\"results\"\n                source={{ kind: \"search\", params: { q, category, part, generationId, year: year ? Number(year) : undefined, versionId, brandId, modelId, ...extra } }}\n                initial={products}\n                total={total}\n                startPage={pageNum}\n                pageSize={PAGE_SIZE}\n                gridClassName=\"grid grid-cols-2 gap-5 md:grid-cols-3 lg:grid-cols-4\"\n              />\n            </>\n          )}\n\n          {/* Real pagination controls (new) -- closes a real, confirmed\n              gap: GET /catalog/products had no pagination at all before\n              this, so every existing page fetched the ENTIRE real\n              catalog on every request. Only rendered when there's\n              genuinely more than one real page -- an honest, not just\n              cosmetic, hidden state. */}\n          {totalPages > 1 && (\n            <>\n              {/* Without JavaScript the list cannot load itself: ordinary links to the other pages. */}\n              <noscript>\n                <nav className=\"mt-8 flex items-center justify-center gap-2\" aria-label={t(lang, \"search_pages_nav\")}>\n                  <Link\n                    href={pageHref(pageNum - 1)}\n                    aria-disabled={pageNum <= 1}\n                    className={`rounded-md border border-line px-3 py-1.5 text-sm ${pageNum <= 1 ? \"pointer-events-none opacity-40\" : \"hover:border-ink\"}`}\n                  >\n                    {t(lang, \"previous\")}\n                  </Link>\n                  <span className=\"text-sm text-muted px-2\">\n                    {t(lang, \"page_x_of_y\", { page: pageNum, total: totalPages })}\n                  </span>\n                  <Link\n                    href={pageHref(pageNum + 1)}\n                    aria-disabled={pageNum >= totalPages}\n                    className={`rounded-md border border-line px-3 py-1.5 text-sm ${pageNum >= totalPages ? \"pointer-events-none opacity-40\" : \"hover:border-ink\"}`}\n                  >\n                    {t(lang, \"next\")}\n                  </Link>\n                </nav>\n\n              </noscript>\n              {/* With JavaScript the same links stay in the page, out of sight, so a search engine can still follow them to every page of results. */}\n              <div aria-hidden=\"true\" className=\"sr-only\">\n                <Link href={pageHref(Math.max(pageNum - 1, 1))} tabIndex={-1}>{t(lang, \"previous\")}</Link>\n                <Link href={pageHref(Math.min(pageNum + 1, totalPages))} tabIndex={-1}>{t(lang, \"next\")}</Link>\n              </div>\n            </>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n"], "text": "import { Suspense } from \"react\";\nimport type { Metadata } from \"next\";\nimport Link from \"@/components/LocLink\";\nimport { fetchCategories, fetchPartsForCategory, fetchProductsPaginated, type CategoryPart } from \"@/lib/api\";\nimport InfiniteProductGrid from \"@/components/InfiniteProductGrid\";\nimport { localizePath, pickName, t } from \"@/lib/i18n\";\nimport { getLang } from \"@/lib/lang\";\nimport { SearchFilters } from \"@/components/SearchFilters\";\nimport { filterHref, readExtraFilters } from \"@/lib/searchFilters\";\nimport { alternatesFor, categoryPageDescription, categoryPageTitle, searchIndexing } from \"@/lib/seo\";\n\nconst PAGE_SIZE = 24;\n\ninterface PageProps {\n  searchParams: Promise<{ q?: string; category?: string; part?: string; generationId?: string; year?: string; versionId?: string; brandId?: string; modelId?: string; page?: string; sort?: string; minPrice?: string; maxPrice?: string; maxDeliveryDays?: string }>;\n}\n\nexport async function generateMetadata({\n  searchParams,\n}: PageProps): Promise<Metadata> {\n  const params = await searchParams;\n  const { q, category, part } = params;\n  // A category page is a real landing page: indexed, with its own title. Every other combination (a typed query, a vehicle filter, page 2...) is a variation of\n  // it: followed, but kept out of the index and pointing at the category page as the one real version (see searchIndexing in lib/seo.ts).\n  const lang = await getLang();\n  const { index, canonicalPath } = searchIndexing(params);\n  let title = q ? t(lang, \"search_results_for\", { q }) : t(lang, \"search_all_parts\");\n  let description: string | undefined;\n  if (!q && category) {\n    const found = (await fetchCategories()).find((c) => c.id === category);\n    if (found) {\n      const categoryName = pickName(lang, found.nameEn, found.nameAr);\n      title = part ? `${part} — ${categoryName}` : categoryPageTitle(categoryName, lang);          // a part page is titled by its part\n      description = categoryPageDescription(categoryName, lang);\n    }\n  }\n  return { title, description, alternates: alternatesFor(lang, canonicalPath), robots: { index, follow: true } };\n}\n\n// Real Server Component -- re-fetches real, filtered results on every\n// real navigation (a new search query, category, real vehicle\n// fitment, or page number is a real new page request in this model),\n// so a search engine can index each real filtered result page on its\n// own, with its own real URL.\nexport default async function SearchPage({ searchParams }: PageProps) {\n  const sp = await searchParams;\n  const { q, category, part, generationId, year, versionId, page } = sp;\n  const brandId = sp.brandId && /^[\\w.:\\-]{1,120}$/.test(sp.brandId) ? sp.brandId : undefined;          // the car chosen step by step (brand, then model, then year)\n  const modelId = sp.modelId && /^[\\w.:\\-]{1,120}$/.test(sp.modelId) ? sp.modelId : undefined;\n  const extra = readExtraFilters((n) => sp[n as keyof typeof sp]);          // sort, price range, delivery time (checked; anything odd is ignored)\n  const lang = await getLang();\n  const pageNum = Math.max(Number(page) || 1, 1);\n  const [categories, { items: products, total, unreachable }, sectionParts] = await Promise.all([\n    fetchCategories(),\n    fetchProductsPaginated({ search: q, category, part, generationId, year: year ? Number(year) : undefined, versionId, brandId, modelId, ...extra, page: pageNum, limit: PAGE_SIZE, lang }),\n    part && category ? fetchPartsForCategory(category).catch((): CategoryPart[] => []) : Promise.resolve<CategoryPart[]>([]),          // only for the part's name in the page's language\n  ]);\n  const totalPages = Math.max(Math.ceil(total / PAGE_SIZE), 1);\n  const sectionName = category ? (() => { const c = categories.find((x) => x.id === category); return c ? pickName(lang, c.nameEn, c.nameAr) : category; })() : null;\n  const current = new URLSearchParams(Object.entries(sp).filter((e): e is [string, string] => typeof e[1] === \"string\"));\n  // A link to another page of the SAME results: every filter is kept (search words, section, part, car, sort, price, delivery), only the page changes.\n  const pageHref = (p: number) => {\n    const href = filterHref(current, {});\n    return p > 1 ? `${href}${href.includes(\"?\") ? \"&\" : \"?\"}page=${p}` : href;\n  };\n  // The title says what is being looked at: the part, else the section, else the search words; under it, where, and how many parts (fit the car).\n  const partInfo = part ? sectionParts.find((p) => p.nameEn === part) : undefined;\n  const title = (part && (partInfo ? pickName(lang, partInfo.nameEn, partInfo.nameAr) : part)) || sectionName || (q ? t(lang, \"search_results_for\", { q }) : t(lang, \"search_all_parts\"));\n  const countText = generationId || modelId || brandId\n    ? (total === 1 ? t(lang, \"sf_fit_car_one\") : t(lang, \"sf_fit_car_many\", { n: total }))\n    : (total === 1 ? t(lang, \"parts_found_one\") : t(lang, \"parts_found\", { n: total }));\n  const heading = (\n    <div className=\"max-sm:hidden\">          {/* on a phone the title and the number of parts are not shown (the filters and the chips say what is shown) */}\n      <h1 className=\"text-2xl font-extrabold tracking-tight [overflow-wrap:anywhere]\">{title}</h1>\n      <p className=\"mt-1 text-sm text-muted\">{part && sectionName ? `${t(lang, \"sf_in_section\", { section: sectionName })} · ` : \"\"}{countText}</p>\n    </div>\n  );\n\n  return (\n    <div className=\"mx-auto max-w-7xl px-2 pb-8 pt-2 sm:px-6 sm:py-10\">\n      {/* on a phone there is no second search box: the one at the top of the page is enough */}\n      <form action={localizePath(lang, \"/search\")} className=\"mb-8 max-sm:hidden\">\n        <input\n          type=\"text\"\n          name=\"q\"\n          defaultValue={q}\n          placeholder={t(lang, \"search_page_placeholder\")}\n          className=\"w-full rounded-md border border-line px-4 py-3 text-sm\"\n        />\n      </form>\n\n      {/* The title, the car, ONE bar of filters (section, part, price, delivery, sort) and the filters that are on, as chips: all in one place above the results, which keep\n          four columns. A real <Suspense> boundary is required around useSearchParams() (a production build fails without one); its fallback is the title alone. */}\n      <Suspense fallback={<div className=\"mb-2 sm:mb-6\">{heading}</div>}>\n        <SearchFilters sections={categories.map((c) => ({ id: c.id, nameEn: c.nameEn, nameAr: c.nameAr }))} heading={heading} />\n      </Suspense>\n      <div className=\"flex flex-col gap-6 lg:flex-row lg:gap-8\">\n        <div className=\"min-w-0 flex-1\">\n          {products.length === 0 ? (\n            <p className=\"text-muted\">\n              {unreachable\n                ? t(lang, \"shop_unreachable\")\n                : generationId || modelId || brandId\n                  ? t(lang, \"no_parts_vehicle\")\n                  : t(lang, \"no_parts_search\")}\n            </p>\n          ) : (\n            <>\n              {pageNum > 1 && <p className=\"mb-4\"><Link href={pageHref(1)} className=\"text-sm font-bold text-navy underline underline-offset-4\">{t(lang, \"grid_back_to_start\")}</Link></p>}\n              {/* The first page is drawn here, on the server (in the page's HTML); the rest loads as the buyer scrolls. The key starts a fresh list whenever the search or a filter changes. */}\n              <InfiniteProductGrid\n                key={`${filterHref(current, {})}|${pageNum}`}\n                id=\"results\"\n                source={{ kind: \"search\", params: { q, category, part, generationId, year: year ? Number(year) : undefined, versionId, brandId, modelId, ...extra } }}\n                initial={products}\n                total={total}\n                startPage={pageNum}\n                pageSize={PAGE_SIZE}\n                gridClassName=\"grid grid-cols-2 gap-2 sm:gap-5 md:grid-cols-3 lg:grid-cols-4\"\n              />\n            </>\n          )}\n\n          {/* Real pagination controls (new) -- closes a real, confirmed\n              gap: GET /catalog/products had no pagination at all before\n              this, so every existing page fetched the ENTIRE real\n              catalog on every request. Only rendered when there's\n              genuinely more than one real page -- an honest, not just\n              cosmetic, hidden state. */}\n          {totalPages > 1 && (\n            <>\n              {/* Without JavaScript the list cannot load itself: ordinary links to the other pages. */}\n              <noscript>\n                <nav className=\"mt-8 flex items-center justify-center gap-2\" aria-label={t(lang, \"search_pages_nav\")}>\n                  <Link\n                    href={pageHref(pageNum - 1)}\n                    aria-disabled={pageNum <= 1}\n                    className={`rounded-md border border-line px-3 py-1.5 text-sm ${pageNum <= 1 ? \"pointer-events-none opacity-40\" : \"hover:border-ink\"}`}\n                  >\n                    {t(lang, \"previous\")}\n                  </Link>\n                  <span className=\"text-sm text-muted px-2\">\n                    {t(lang, \"page_x_of_y\", { page: pageNum, total: totalPages })}\n                  </span>\n                  <Link\n                    href={pageHref(pageNum + 1)}\n                    aria-disabled={pageNum >= totalPages}\n                    className={`rounded-md border border-line px-3 py-1.5 text-sm ${pageNum >= totalPages ? \"pointer-events-none opacity-40\" : \"hover:border-ink\"}`}\n                  >\n                    {t(lang, \"next\")}\n                  </Link>\n                </nav>\n\n              </noscript>\n              {/* With JavaScript the same links stay in the page, out of sight, so a search engine can still follow them to every page of results. */}\n              <div aria-hidden=\"true\" className=\"sr-only\">\n                <Link href={pageHref(Math.max(pageNum - 1, 1))} tabIndex={-1}>{t(lang, \"previous\")}</Link>\n                <Link href={pageHref(Math.min(pageNum + 1, totalPages))} tabIndex={-1}>{t(lang, \"next\")}</Link>\n              </div>\n            </>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n"}]};
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const write = process.argv.includes('--write');
const plan = [];
let problems = 0;
const once = (s, a) => s.split(a).length === 2;
const read = (file) => { const p = path.join(root, file); return fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null; };
function edit(file, what, done, change) {
  const s = read(file);
  if (s === null) { console.log(`MISSING   ${file}: not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; return; }
  if (s.replace(/\r\n/g, '\n').includes(done)) { console.log(`already   ${file}: ${what}`); return; }
  const eol = s.includes('\r\n') ? '\r\n' : '\n';
  const out = change(s.replace(/\r\n/g, '\n'));
  if (typeof out !== 'string') { console.log(`REFUSED   ${file}: ${out && out.why ? out.why : 'its text is not what this patch expects'}, so nothing was changed. Send this file.`); problems++; return; }
  plan.push({ file, what, before: s, after: out.replace(/\n/g, eol) });
}

for (const e of DATA.created) {
  const p = path.join(root, e.file);
  if (e.base64) {      // a picture: written as it is
    const bytes = Buffer.from(e.base64, 'base64');
    if (fs.existsSync(p)) {
      if (fs.readFileSync(p).equals(bytes)) { console.log(`already   ${e.file}: ${e.what}`); continue; }
      console.log(`REFUSED   ${e.file}: a different file with this name is already there, so nothing was changed. Send this file.`); problems++; continue;
    }
    if (!fs.existsSync(path.dirname(p))) { console.log(`MISSING   ${path.dirname(e.file)}: folder not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; continue; }
    plan.push({ file: e.file, what: e.what, before: null, after: bytes });
    continue;
  }
  if (fs.existsSync(p)) {
    if (fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n') === e.text) { console.log(`already   ${e.file}: ${e.what}`); continue; }
    console.log(`REFUSED   ${e.file}: a different file with this name is already there, so nothing was changed. Send this file.`); problems++; continue;
  }
  // a new folder (services/api/src/modules/draftPhotos) is made, but only inside one that is already there
  if (!fs.existsSync(path.dirname(path.dirname(p)))) { console.log(`MISSING   ${path.dirname(path.dirname(e.file))}: folder not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; continue; }
  plan.push({ file: e.file, what: e.what, before: null, after: e.text });
}
for (const e of DATA.replaced || []) {
  edit(e.file, e.what, e.done, (s) => (e.from.includes(s) ? e.text : { why: 'it is neither the original nor the version patch-web-search-phone made (send this file)' }));
}
for (const e of DATA.anchored) {
  // a test file: changed when it is there and as expected, otherwise left as it is (it does not stop the patch)
  if (e.optional) {
    const s = read(e.file);
    if (s === null) { console.log(`skipped   ${e.file}: not found (a test file; nothing to do)`); continue; }
    const n = s.replace(/\r\n/g, '\n');
    if (!n.includes(e.done) && (e.pairs.some(([a, , all]) => all !== 'maybe' && all !== 'alts' && !once(n, a)) || (e.block && (!n.includes(e.block.from) || !n.includes(e.block.to))))) { console.log(`skipped   ${e.file}: not as expected, left as it is (${e.what})`); continue; }
  }
  edit(e.file, e.what, e.done, (s) => {
    let out = s;
    for (const [a, b, all] of e.pairs) {
      if (all === 'alts') { const hit = a.find(([x]) => once(out, x)); if (!hit) return { why: `this part was not found: "${a[a.length - 1][0].split('\n').find((l) => l.trim()).trim().slice(0, 90)}"` }; out = out.replace(hit[0], () => hit[1]); continue; }
      if (all === 'maybe') { if (once(out, a)) out = out.replace(a, () => b); continue; }
      if (all) { if (!out.includes(a)) return { why: `this part was not found: "${a.split('\n').find((l) => l.trim()).trim().slice(0, 90)}"` }; out = out.split(a).join(b); continue; } if (!once(out, a)) return { why: `this part was not found: "${a.split('\n').find((l) => l.trim()).trim().slice(0, 90)}"` }; out = out.replace(a, () => b); }
    if (e.region) {
      const r = e.region; const i = out.indexOf(r.from); const j = i < 0 ? -1 : out.indexOf(r.to, i);
      if (i < 0 || j < 0) return { why: `the part starting "${r.from.trim().slice(0, 60)}" was not found` };
      const seg = out.slice(i, j);
      if (r.must && !seg.includes(r.must)) return { why: `"${r.must}" was not found in the part starting "${r.from.trim().slice(0, 60)}"` };
      const changed = seg.replace(new RegExp(r.find, 'g'), r.repl);
      if (changed === seg) return { why: `nothing to change in the part starting "${r.from.trim().slice(0, 60)}"` };
      out = out.slice(0, i) + changed + out.slice(j);
    }
    if (e.block) {
      const i = out.indexOf(e.block.from); const j = i < 0 ? -1 : out.indexOf(e.block.to, i);
      if (i < 0 || j < 0) return { why: `the part starting "${e.block.from.trim().slice(0, 60)}" was not found` };
      out = out.slice(0, i) + e.block.text + out.slice(e.block.includeTo ? j + e.block.to.length : j);
    }
    return out;
  });
}
if (DATA.mount) edit('services/api/src/index.js', DATA.mount.what, DATA.mount.done, (s) => {
  const m = s.match(/\n([ \t]*)app\.use\('\/payouts', payoutsRoutes\);[^\n]*/);
  if (!m) return { why: "the line app.use('/payouts', payoutsRoutes); was not found" };
  const at = m.index + m[0].length;
  return s.slice(0, at) + `\n${m[1]}${DATA.mount.line}` + s.slice(at);
});
if (problems > 0) { console.log('\nNothing was changed, because of the problem(s) above.'); process.exit(1); }
for (const c of plan) {
  if (write) {
    const p = path.join(root, c.file);
    if (c.before !== null) fs.writeFileSync(`${p}.before-patch-web-search-phone-v2`, c.before);
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, c.after);
    console.log(`${c.before === null ? 'created ' : 'patched '}  ${c.file}: ${c.what}`);
  } else console.log(`would     ${c.file}: ${c.what}`);
}
if (!write && plan.length) console.log('\nDry run only. Add --write to apply.');
if (write && plan.length) console.log('\nDone. Then: website: Ctrl+F5');
